import { Prisma } from "@prisma/client";
import { requireAdmin } from "@/lib/auth"; import { db } from "@/lib/db"; import { handleApiError, ok } from "@/lib/http";
export const dynamic = "force-dynamic";
export async function GET(request: Request) { try { await requireAdmin(); const q = new URL(request.url).searchParams; const page = Math.max(1, Number(q.get("page") || 1)); const pageSize = Math.min(100, Math.max(1, Number(q.get("pageSize") || 20))); const search = q.get("search")?.trim(); const level = q.get("level"); const status = q.get("status"); const area = q.get("area"); const zone = q.get("zone"); const where: Prisma.VendorWhereInput = { ...(search ? { OR: ["name", "area", "zone", "phone"].map((field) => ({ [field]: { contains: search, mode: "insensitive" } })) } : {}), ...(level !== null && level !== "" ? { verificationLevel: Number(level) } : {}), ...(status ? { status: status as never } : {}), ...(area ? { area } : {}), ...(zone ? { zone } : {}) }; const sort = ["createdAt", "ratingAvg", "weightedRatingAvg", "ratingCount"].includes(q.get("sort") || "") ? q.get("sort")! : "createdAt"; const direction = q.get("direction") === "asc" ? "asc" : "desc"; const [items, total] = await Promise.all([db.vendor.findMany({ where, skip: (page - 1) * pageSize, take: pageSize, orderBy: { [sort]: direction }, include: { addedBy: { select: { id: true, name: true } }, _count: { select: { reviews: true, photos: true, reports: true } } } }), db.vendor.count({ where })]); return ok({ items, total, page, pageSize, pages: Math.ceil(total / pageSize) }); } catch (error) { return handleApiError(error); } }
